import json,gzip,collections,math
from pathlib import Path
from muc_one_span.read_dominance import evaluate_candidate_pair_dominance
for label,values in [('missing opponent',{f'r{i}':{'c2':1} for i in range(3)}),('ambiguous denominator',{**{f'r{i}':{'c1':1000,'c2':1000} for i in range(1000)},**{f'd{i}':{'c1':1000,'c2':1100} for i in range(3)}})]:
 print(label,evaluate_candidate_pair_dominance(values,'c1','c2'))
B,C=[json.loads((Path('tests/results')/x/'evaluation_report.json').read_text()) for x in ('baseline_dev_140','candidate_dev_140')]
for p in ('hifi','ont'):
 for key in ('event_tp','event_fp'):
  print(p,key,[(s['sample'],b['metrics'][key]['min'],s['metrics'][key]['min']) for b,s in zip(B['samples'],C['samples'],strict=True) if s['sample'].endswith(p) and ((key=='event_tp' and s['metrics'][key]['min']<b['metrics'][key]['min']) or (key=='event_fp' and s['metrics'][key]['min']>b['metrics'][key]['min']))])
print('gap1 all hifi',[(s['sample'],s['metrics']['all_counts_exact']['min']) for s in C['samples'] if 'gap1' in s['sample'] and s['sample'].endswith('hifi')])
print('asym',[(s['sample'],s['metrics']['all_counts_exact']['min']) for s in C['samples'] if '25_140' in s['sample']])
# Check VCF representation edge cases among candidate dev outputs only.
stats=collections.Counter();examples={}
for s in C['samples']:
 for p in (Path('tests/results/candidate_dev_140')/s['sample']).glob('allele_*/variants.vcf.gz'):
  with gzip.open(p,'rt') as f:
   for line in f:
    if line.startswith('#'):continue
    parts=line.rstrip().split('\\t');fmt=dict(zip(parts[8].split(':'),parts[9].split(':')))
    for condition,key in [(',' in parts[4],'multiallelic'),(',' in fmt.get('AF',''),'multi_AF'),(fmt.get('GT')=='0/1','heterozygous'),(fmt.get('AF')=='0.5','AF exactly 0.5')]:
     if condition:stats[key]+=1;examples.setdefault(key,(s['sample'],p.parent.name,line.rstrip()[:240]))
print('VCF stats',stats,examples)
print('paired nominal McNemar p two-sided HiFi/ONT',2/2**14,1.0)
PY"

